前言 外观模式（Facade Pattern）是一种结构型设计模式，它的核心思想是：为子系统中的一组接口提供一个一致的界面（Facade），使得子系统更加容易使用。
核心思想：封装复杂性，提供简化的高层接口。
一、为什么需要外观模式 1.1 子系统复杂性 假设我们正在开发一个智能家居系统，有灯光、空调、音响、窗帘等多个子系统：
// 不用外观模式：客户端需要了解所有子系统的细节 public class Client { public void watchMovie() { Light light = new Light(); light.dim(20); AirConditioner ac = new AirConditioner(); ac.setTemperature(24); ac.setMode("cooling"); ac.setFanSpeed("medium"); ac.turnOn(); SoundSystem sound = new SoundSystem(); sound.setVolume(30); sound.setSurround(true); sound.setInput("HDMI"); sound.turnOn(); Projector projector = new Projector(); projector.setInput("HDMI"); projector.setMode("cinema"); projector.turnOn(); Curtain curtain = new Curtain(); curtain.close(); } } 客户端需要了解每个子系统的初始化细节和调用顺序，耦合度极高。外观模式将这些复杂性封装在一个简单的接口后面。
1.2 迪米特法则 外观模式符合迪米特法则（Law of Demeter）：一个对象应该对其他对象有尽可能少的了解。客户端只需要与外观对象交互，不需要了解子系统内部结构。
二、外观模式的结构 2.1 类图 ┌───────────┐ ┌──────────────┐ │ Client │─────>│ Facade │ └───────────┘ │──────────────│ │ +operation() │ └──────┬───────┘ │ ┌───────┬───────┼───────┬───────┐ │ │ │ │ │ ┌────┴──┐ ┌──┴───┐ ┌┴────┐ ┌┴─────┐ ┌┴──────┐ │Sub A │ │Sub B │ │Sub C│ │Sub D │ │Sub E │ └───────┘ └──────┘ └─────┘ └──────┘ └───────┘ 2.2 核心角色 角色 职责 Facade（外观） 提供简化的高层接口，委托子系统完成工作 Subsystem（子系统） 实现具体功能，不知道 Facade 的存在 Client（客户端） 通过 Facade 与子系统交互 2.3 关键特点 外观模式没有抽象层，不像其他模式那样有复杂的继承体系。它的核心就是封装和委托：
Facade 知道哪些子系统负责处理哪些请求 子系统不知道 Facade 的存在 客户端只与 Facade 交互 2.4 完整实现 // ========== 1. 子系统：灯光 ========== public class Light { public void turnOn() { System.out.println("💡 灯光已开启"); } public void turnOff() { System.out.println("💡 灯光已关闭"); } public void dim(int level) { System.out.println("💡 灯光调暗至 " + level + "%"); } } // ========== 2. 子系统：空调 ========== public class AirConditioner { private int temperature = 26; private String mode = "auto"; public void turnOn() { System.out.println("❄️ 空调已开启"); } public void turnOff() { System.out.println("❄️ 空调已关闭"); } public void setTemperature(int temp) { this.temperature = temp; System.out.println("❄️ 空调温度设为 " + temp + "°C"); } public void setMode(String mode) { this.mode = mode; System.out.println("❄️ 空调模式设为 " + mode); } } // ========== 3. 子系统：音响 ========== public class SoundSystem { private int volume = 20; public void turnOn() { System.out.println("🔊 音响已开启"); } public void turnOff() { System.out.println("🔊 音响已关闭"); } public void setVolume(int vol) { this.volume = vol; System.out.println("🔊 音量设为 " + vol); } public void setSurround(boolean enable) { System.out.println("🔊 环绕声 " + (enable ? "开启" : "关闭")); } } // ========== 4. 子系统：投影仪 ========== public class Projector { public void turnOn() { System.out.println("📽️ 投影仪已开启"); } public void turnOff() { System.out.println("📽️ 投影仪已关闭"); } public void setInput(String input) { System.out.println("📽️ 输入源设为 " + input); } public void setMode(String mode) { System.out.println("📽️ 显示模式设为 " + mode); } } // ========== 5. 子系统：窗帘 ========== public class Curtain { public void open() { System.out.println("🪟 窗帘已打开"); } public void close() { System.out.println("🪟 窗帘已关闭"); } } // ========== 6. 外观：智能家居控制 ========== public class SmartHomeFacade { private final Light light; private final AirConditioner ac; private final SoundSystem sound; private final Projector projector; private final Curtain curtain; public SmartHomeFacade() { this.light = new Light(); this.ac = new AirConditioner(); this.sound = new SoundSystem(); this.projector = new Projector(); this.curtain = new Curtain(); } // 场景1：看电影 public void watchMovie() { System.out.println("🎬 准备看电影..."); curtain.close(); light.dim(10); ac.setTemperature(24); ac.setMode("cooling"); ac.turnOn(); projector.setInput("HDMI"); projector.setMode("cinema"); projector.turnOn(); sound.setSurround(true); sound.setVolume(30); sound.turnOn(); System.out.println("🎬 电影模式就绪！"); } // 场景2：结束电影 public void endMovie() { System.out.println("🎬 结束电影..."); sound.turnOff(); projector.turnOff(); light.turnOn(); curtain.open(); System.out.println("🎬 已退出电影模式"); } // 场景3：阅读模式 public void readingMode() { System.out.println("📖 进入阅读模式..."); curtain.open(); light.turnOn(); ac.setTemperature(25); ac.setMode("auto"); ac.turnOn(); sound.turnOff(); System.out.println("📖 阅读模式就绪！"); } // 场景4：睡眠模式 public void sleepMode() { System.out.println("😴 进入睡眠模式..."); light.turnOff(); curtain.close(); sound.turnOff(); projector.turnOff(); ac.setTemperature(26); ac.setMode("sleep"); ac.turnOn(); System.out.println("😴 睡眠模式就绪！"); } } // ========== 7. 客户端 ========== public class SmartHomeDemo { public static void main(String[] args) { SmartHomeFacade smartHome = new SmartHomeFacade(); // 简单的接口调用，无需了解子系统细节 smartHome.watchMovie(); System.out.println(); smartHome.endMovie(); System.out.println(); smartHome.readingMode(); System.out.println(); smartHome.sleepMode(); } } 运行结果：
